import torch


def gen_inputs(ctx, device):
    dtype = getattr(torch, ctx["weight__dtype"])
    shape = tuple(ctx["weight__shape"])
    # Source builds weight as torch.tensor([0.25], dtype=dtype)
    return {"weight": torch.full(shape, 0.25, dtype=dtype, device=device)}


def run(grad_output, x, weight):
    return torch.ops.aten._prelu_kernel_backward(grad_output, x, weight)
